package dev.zomboid.clans;
import java.util.*;
/** Local fallback for wave mobs, only after normal navigation has stalled. */
public final class Siege {
 static int[] heights(int min,int max,int preferred){int[] a=new int[max-min];int n=0;for(int d=0;n<a.length;d++){int up=preferred+d,down=preferred-d;if(up>=min&&up<max)a[n++]=up;if(d>0&&down>=min&&down<max)a[n++]=down;}return a;}
 static int priority(String id){return id.contains("door")?0:(id.contains("glass")||id.contains("window"))?1:2;}
 static boolean protectedBlock(String id,float hardness){return hardness<0||id.equals(Nexus.ID)||id.contains("chest")||id.contains("barrel")||id.contains("shulker")||id.contains("bedrock");}
 public static void move(Object mob,Object goal){Object level=R.call(mob,"level"),nav=R.call(mob,"getNavigation"),tag=Pve.tag(mob);long now=R.lng(R.call(level,"getGameTime"));Object direct=R.call(nav,"createPath",goal,1);Object target=goal;if(direct!=null&&R.yes(R.call(direct,"canReach"))){R.call(tag,"putBoolean","SiegeHasEntry",false);R.call(nav,"moveTo",direct,1d);return;}if(direct==null||!R.yes(R.call(direct,"canReach"))){if(now>=R.lng(R.call(tag,"getLong","SiegeScan"))){R.call(tag,"putLong","SiegeScan",now+100);int rank=99;double nearest=Double.MAX_VALUE;Object found=null;int x=(int)Math.floor(R.coord(mob,"X")),y=(int)Math.floor(R.coord(mob,"Y")),z=(int)Math.floor(R.coord(mob,"Z"));for(int dx=-6;dx<=6;dx++)for(int dz=-6;dz<=6;dz++)for(int dy=-2;dy<=2;dy++){Object pos=R.make("net.minecraft.core.BlockPos",x+dx,y+dy,z+dz);if(!R.yes(R.call(level,"hasChunkAt",pos)))continue;Object state=R.call(level,"getBlockState",pos);if(R.yes(R.call(state,"isAir")))continue;String id=R.call(R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"BLOCK"),"getKey",R.call(state,"getBlock")).toString();int p=priority(id);if(p>1)continue;double distance=dx*dx+dz*dz+dy*dy;if(p>rank||p==rank&&distance>=nearest)continue;Object path=R.call(nav,"createPath",pos,1);if(path==null||!R.yes(R.call(path,"canReach")))continue;found=pos;rank=p;nearest=distance;}R.call(tag,"putBoolean","SiegeHasEntry",found!=null);if(found!=null)R.call(tag,"putLong","SiegeEntry",R.call(found,"asLong"));}if(R.yes(R.call(tag,"getBoolean","SiegeHasEntry")))target=R.call(R.type("net.minecraft.core.BlockPos"),"of",R.call(tag,"getLong","SiegeEntry"));}if(target==goal&&!R.yes(R.call(tag,"getBoolean","SiegeHasEntry"))){if(direct!=null&&((Number)R.call(direct,"getNodeCount")).intValue()>1){R.call(nav,"moveTo",direct,1d);return;}Object ground=R.make("net.minecraft.core.BlockPos",(int)R.coord(goal,"X"),(int)Math.floor(R.coord(mob,"Y")),(int)R.coord(goal,"Z")),approach=R.call(nav,"createPath",ground,1);if(approach!=null&&((Number)R.call(approach,"getNodeCount")).intValue()>1){R.call(nav,"moveTo",approach,1d);return;}}R.call(nav,"moveTo",R.coord(target,"X")+.5,(double)R.coord(target,"Y"),R.coord(target,"Z")+.5,1d);}
 public static void tick(Object mob,Object goal){Object level=R.call(mob,"level"),tag=Pve.tag(mob);long now=R.lng(R.call(level,"getGameTime"));if(now<R.lng(R.call(tag,"getLong","SiegeNext")))return;R.call(tag,"putLong","SiegeNext",now+20);double x=R.coord(mob,"X"),y=R.coord(mob,"Y"),z=R.coord(mob,"Z");double lastY=R.num(R.call(tag,"getDouble","SiegeY"));R.call(tag,"putDouble","SiegeY",y);double lastX=R.num(R.call(tag,"getDouble","SiegeX")),lastZ=R.num(R.call(tag,"getDouble","SiegeZ"));R.call(tag,"putDouble","SiegeX",x);R.call(tag,"putDouble","SiegeZ",z);int stuck=(Math.abs(x-lastX)+Math.abs(y-lastY)+Math.abs(z-lastZ)<.3)?((Number)R.call(tag,"getInt","SiegeStuck")).intValue()+1:0;R.call(tag,"putInt","SiegeStuck",stuck);if(stuck<3)return;
 Object best=null,bestState=null;int rank=99;if(R.yes(R.call(tag,"getBoolean","SiegeHasEntry")))goal=R.call(R.type("net.minecraft.core.BlockPos"),"of",R.call(tag,"getLong","SiegeEntry"));double gx=R.coord(goal,"X")+.5,gz=R.coord(goal,"Z")+.5;for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)for(int dy=0;dy<=1;dy++){if(dx==0&&dz==0)continue;if(dx*(gx-x)+dz*(gz-z)<=0)continue;Object pos=R.make("net.minecraft.core.BlockPos",(int)Math.floor(x)+dx,(int)Math.floor(y)+dy,(int)Math.floor(z)+dz),state=R.call(level,"getBlockState",pos);if(R.yes(R.call(state,"isAir")))continue;String id=R.call(R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"BLOCK"),"getKey",R.call(state,"getBlock")).toString();float hard=((Number)R.call(state,"getDestroySpeed",level,pos)).floatValue();if(protectedBlock(id,hard)||R.call(level,"getBlockEntity",pos)!=null)continue;int p=priority(id);if(p<rank){rank=p;best=pos;bestState=state;}}
 if(best!=null){Object open=R.get(R.type("net.minecraft.world.level.block.state.properties.BlockStateProperties"),"OPEN");if(rank==0&&R.yes(R.call(bestState,"hasProperty",open))){if(!R.yes(R.call(bestState,"getValue",open))){R.call(level,"setBlock",best,R.call(bestState,"setValue",open,true),3);R.call(mob,"swing",R.get(R.type("net.minecraft.world.InteractionHand"),"MAIN_HAND"));return;}}
 int required=rank==0?4:rank==1?5:8;if(stuck>=required){R.call(mob,"swing",R.get(R.type("net.minecraft.world.InteractionHand"),"MAIN_HAND"));R.call(level,"destroyBlock",best,true,mob);R.call(tag,"putInt","SiegeStuck",0);}return;}
 if(stuck<10||R.coord(goal,"Y")<=y)return;int dx=(int)Math.signum(gx-x),dz=(int)Math.signum(gz-z);Object pos=R.make("net.minecraft.core.BlockPos",(int)Math.floor(x)+dx,(int)Math.floor(y),(int)Math.floor(z)+dz),state=R.call(level,"getBlockState",pos);if(!R.yes(R.call(state,"isAir")))return;int built=((Number)R.call(tag,"getInt","SiegeBuilt")).intValue();if(built>=16)return;R.call(level,"setBlock",pos,R.call(R.get(R.type("net.minecraft.world.level.block.Blocks"),"COBBLESTONE"),"defaultBlockState"),3);R.call(tag,"putInt","SiegeBuilt",built+1);R.call(tag,"putInt","SiegeStuck",0);
 }
}
